const body = $json.body ?? $json;

const isTelegram =
  !!($json.message?.chat?.id || $json.message?.text);

const source = isTelegram ? 'telegram' : 'web';

const text = String(
  $json.message?.text ??
  body.message ??
  body.text ??
  body.query ??
  body.messageText ??
  body.orderText ??
  body.caption ??
  ''
).trim();

const chatIdValue =
  $json.message?.chat?.id ??
  body.chat_id ??
  body.chatId ??
  body.session_id ??
  body.user_id ??
  body.phone ??
  body.email ??
  body.visitor_id ??
  `web-${Date.now()}`;

const chatId = String(chatIdValue);

const userName = String(
  $json.message?.from?.username ??
  $json.message?.from?.first_name ??
  body.user_name ??
  body.username ??
  body.name ??
  ''
).trim();

const fullName = String(
  [
    $json.message?.from?.first_name,
    $json.message?.from?.last_name
  ]
    .filter(Boolean)
    .join(' ') ||
    body.full_name ||
    body.name ||
    userName
).trim();

return {
  json: {
    source,
    text,
    sessionId: chatId,
    chatId,
    userName,
    fullName,
    rawPayloadText: JSON.stringify($json),
    telegramMessageId: String(
      $json.message?.message_id ??
      body.message_id ??
      ''
    )
  }
};

const input = $('Normalize Input').first().json;
const aiRaw = String($json.output ?? $json.response ?? $json.text ?? $json.message ?? '').trim();
const fallbackText = String(input.text || '').toLowerCase().trim();
const orderIdMatch = fallbackText.match(/(?:order\s*#?|#)\s*(\d{1,12})/i) || fallbackText.match(/\b(\d{1,12})\b/);
const fallbackOrderId = orderIdMatch ? Number(orderIdMatch[1]) : null;
const isGreeting = /^(hi|hello|hey|hii|hola|good morning|good evening|\/start)\b/.test(fallbackText) || /\b(hello|hi|hey|hii|helloe|hellow|helllo)\b/.test(fallbackText);
const deleteSignal = /\b(delete|remove|cancel|discard)\b/.test(fallbackText);
const updateSignal = /\b(update|change|edit|modify|replace)\b/.test(fallbackText);
const statusSignal = /\b(status|track|track order|where is my order|check order|lookup|find order)\b/.test(fallbackText);
const createSignal = /\b(order|buy|purchase|place|checkout|cart)\b/.test(fallbackText) || /\b\d+\s*(pcs|pc|pieces|items|x)\b/.test(fallbackText);
const genericWords = new Set(['order','buy','purchase','place','checkout','cart','hello','hi','hey','hii','help','update','delete','remove','cancel','status','track','check','need','want','please','product','item','items']);
const concreteTokens = fallbackText.split(/\s+/).filter(Boolean).filter(token => !genericWords.has(token) && !/^\d+$/.test(token));
const hasProductClue = !!fallbackText.match(/\b\d+\s*(pcs|pc|pieces|items|x)?\b/) || concreteTokens.length >= 2;
const orderIntentHint = deleteSignal ? 'delete' : updateSignal ? 'update' : statusSignal ? 'status' : createSignal ? 'create' : '';
const intent = deleteSignal && fallbackOrderId ? 'delete' : updateSignal && fallbackOrderId ? 'update' : statusSignal && fallbackOrderId ? 'status' : createSignal && hasProductClue ? 'create' : 'greeting';
const quantityMatch = fallbackText.match(/\b(\d+)\s*(pcs|pc|pieces|items|x)?\b/);
const quantity = quantityMatch ? Number(quantityMatch[1]) : null;
const itemName = String(input.text || '').trim();
const prompt = `You are a professional generative dropshipping assistant.
User channel: ${input.source}
User message: ${input.text}
Detected intent: ${intent}
Order intent hint: ${orderIntentHint || 'none'}
Known order clues: itemName=${itemName || 'none'}, quantity=${quantity ?? 'none'}, orderId=${fallbackOrderId ?? 'none'}
Rules:
- Never repeat the user's message back verbatim.
- If the user says hello or asks what you can do, respond with a warm professional greeting and explain you can place, update, or cancel an order.
- If orderIntentHint is create and required details are missing, ask one short question about the product, quantity, or delivery details.
- If orderIntentHint is update, delete, or status and details are missing, ask one short question for the order id.
- Keep the answer concise, natural, and human.
- Do not mention SQL, JSON, tools, memory, or internal workflow.
Return only the final reply text.`;
const replyDraft = aiRaw || (orderIntentHint === 'create' ? 'Which product would you like to order, and how many units do you need?' : orderIntentHint === 'update' ? 'Please share your order ID and what you would like to change.' : orderIntentHint === 'delete' ? 'Please share your order ID so I can help with the cancellation.' : orderIntentHint === 'status' ? 'Please share your order ID so I can check the latest status.' : 'Hi! Welcome to our dropshipping support. I can help you place, update, or cancel an order. Send me the product name, quantity, and delivery details to get started.');
return [{
  json: {
    ...input,
    aiRaw,
    intent,
    orderIntentHint,
    prompt,
    replyDraft,
    orderId: fallbackOrderId,
    quantity,
    itemName,
    needsSql: intent !== 'greeting',
    itemNameEsc: String(itemName).replace(/'/g, "''"),
    notesEsc: String(`intent:${intent}; source:${input.source}; hint:${orderIntentHint || 'none'}`).replace(/'/g, "''")
  }
}];

const input = $('Normalize Input').first().json;
const aiState = $json;
const detected = $('Detect Intent').first().json;
const candidates = [aiState.output, aiState.response, aiState.text, aiState.message, aiState.result, aiState.replyText, aiState.content, aiState.data?.output, aiState.data?.text]
  .filter(value => typeof value === 'string')
  .map(value => value.trim())
  .filter(Boolean);
const aiReply = candidates[0] || '';
const fallbackReply = (() => {
  if (detected.orderIntentHint === 'create' && detected.intent === 'greeting') {
    return 'Which product would you like to order, and how many units do you need?';
  }
  if (detected.orderIntentHint === 'update' && detected.intent === 'greeting') {
    return 'Please share your order ID and what you would like to change.';
  }
  if (detected.orderIntentHint === 'delete' && detected.intent === 'greeting') {
    return 'Please share your order ID so I can help with the cancellation.';
  }
  if (detected.orderIntentHint === 'status' && detected.intent === 'greeting') {
    return 'Please share your order ID so I can check the latest status.';
  }
  switch (detected.intent || input.intent || 'greeting') {
    case 'create':
      return 'Which product would you like to order, and how many units do you need?';
    case 'update':
      return 'Please share your order ID and what you would like to change.';
    case 'delete':
      return 'Please share your order ID so I can help with the cancellation.';
    case 'status':
      return 'Please share your order ID so I can check the latest status.';
    default:
      return 'Hi! Welcome to our dropshipping support. I can help you place, update, or cancel an order. Send me the product name, quantity, and delivery details to get started.';
  }
})();
const normalizedUserText = String(input.text || '').trim().toLowerCase();
const normalizedAiText = String(aiReply || '').trim().toLowerCase();
const aiLooksLikeEcho = !!normalizedAiText && !!normalizedUserText && normalizedAiText === normalizedUserText;
const finalReply = aiReply && !aiLooksLikeEcho ? aiReply : fallbackReply;
return [{
  json: {
    ...input,
    ...detected,
    aiRaw: aiReply,
    replyDraft: finalReply,
    replyText: finalReply,
    chatId: input.chatId,
    source: input.source,
    intent: detected.intent || input.intent || 'greeting'
  }
}];
